import { useCallback, useEffect, useState, type SubmitEvent } from 'react'
import {
  createExpense,
  fetchExpenses,
  ValidationError,
  type Expense,
} from './api'

const FIELDS = ['label', 'amount', 'currency'] as const

export function App() {
  const [expenses, setExpenses] = useState<Expense[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  const load = useCallback(async (signal?: AbortSignal) => {
    try {
      setExpenses(await fetchExpenses(signal))
      setLoadError(null)
    } catch (e) {
      if (signal?.aborted) return
      setLoadError(e instanceof Error ? e.message : 'Failed to load expenses')
    } finally {
      if (!signal?.aborted) setLoading(false)
    }
  }, [])

  useEffect(() => {
    const controller = new AbortController()
    void load(controller.signal)
    return () => controller.abort()
  }, [load])

  async function onSubmit(event: SubmitEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = event.currentTarget
    const data = new FormData(form)
    const amountText = String(data.get('amount') ?? '').trim()
    setSubmitting(true)
    setErrors({})
    setFormError(null)
    try {
      await createExpense({
        label: String(data.get('label') ?? '').trim(),
        amount: amountText === '' ? NaN : Number(amountText),
        currency: String(data.get('currency') ?? '').trim(),
      })
      form.reset()
      await load()
    } catch (e) {
      if (e instanceof ValidationError) {
        setErrors(e.errors)
        const unknown = Object.entries(e.errors)
          .filter(([k]) => !(FIELDS as readonly string[]).includes(k))
          .map(([, m]) => m)
        if (unknown.length) setFormError(unknown.join(' '))
      } else {
        setFormError(e instanceof Error ? e.message : 'Submission failed')
      }
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <main>
      <h1>My expenses</h1>

      {loading ? (
        <p>Loading…</p>
      ) : loadError ? (
        <p role="alert">{loadError}</p>
      ) : expenses.length === 0 ? (
        <p>No expenses yet.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>Label</th>
              <th>Amount</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {expenses.map((x) => (
              <tr key={x.id}>
                <td>{x.label}</td>
                <td>
                  {new Intl.NumberFormat(undefined, {
                    style: 'currency',
                    currency: x.currency,
                  }).format(x.amount)}
                </td>
                <td>{x.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <h2>New expense</h2>
      <form onSubmit={onSubmit} noValidate>
        {FIELDS.map((name) => (
          <div key={name}>
            <label htmlFor={`expense-${name}`}>
              {name[0].toUpperCase() + name.slice(1)}
            </label>
            <input
              id={`expense-${name}`}
              name={name}
              type={name === 'amount' ? 'number' : 'text'}
              step={name === 'amount' ? 'any' : undefined}
              aria-invalid={errors[name] ? true : undefined}
              aria-describedby={errors[name] ? `expense-${name}-error` : undefined}
            />
            {errors[name] && (
              <span id={`expense-${name}-error`} role="alert">
                {errors[name]}
              </span>
            )}
          </div>
        ))}
        {formError && <p role="alert">{formError}</p>}
        <button type="submit" disabled={submitting}>
          {submitting ? 'Submitting…' : 'Submit'}
        </button>
      </form>
    </main>
  )
}
